INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422596, 16112, 'The Guardian', 'en', 'Uefa raises stakes with criminal complaint in battle to unseat Infantino', 'https://www.theguardian.com/football/2026/aug/27/uefa-criminal-complaint-plan-fifa-gianni-infantino-analysis', 'Uefa has begun a legal process against the embattled Fifa president but it will still be an uphill struggle to remove him Anyone who interpreted Uefa’s decision to withdraw a proposed boycott of Fifa competitions, revealed by the Guardian on Wednesday , as a backward step in the attempt to remove Gianni Infantino as Fifa’s president has been quickly disabused of that notion. In a stunning development that overshadowed one of the biggest days in the European football calendar as national football federation and club executives gathered for the Champions League draw in Monte Carlo, Uefa announce', 'https://i.guim.co.uk/img/media/15b7d537fad1f3439ddcaf838d3fa0a55e1bb785/224_0_3391_2712/master/3391.jpg?width=140&quality=85&auto=format&fit=max&s=46284dca2da432e60d5862049b9f37dc', '2026-08-27T19:00:36+00:00', '2026-08-28T12:49:07.391436'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
